<?php
declare(strict_types=1);namespace App\Application\Underwriting;
use App\Application\{Audit\AuditWriter,Events\OutboxWriter};use App\Models\{Proposal,UnderwritingCase,UnderwritingDecision,UnderwritingReferralTask,User};use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
final class UnderwritingService{public function __construct(private AuditWriter$audit,private OutboxWriter$outbox){}public function assign(UnderwritingCase$c,User$assignee,User$actor):UnderwritingCase{if(!in_array($c->status,['QUEUED','IN_REVIEW'],true))throw ValidationException::withMessages(['status'=>__('wave3.case_closed')]);$c->update(['assigned_to'=>$assignee->id,'status'=>'IN_REVIEW']);$this->audit->record('underwriting.case.assigned','underwriting_case',$c->id,['assigned_to'=>$assignee->id]);return$c->refresh();}public function resolveReferral(UnderwritingReferralTask$t,string$notes,User$actor):UnderwritingReferralTask{if($t->status!=='OPEN')throw ValidationException::withMessages(['status'=>__('wave3.referral_closed')]);$t->update(['status'=>'RESOLVED','resolution_notes'=>$notes,'resolved_by'=>$actor->id,'resolved_at'=>now()]);$this->audit->record('underwriting.referral.resolved','underwriting_referral',$t->id,[]);return$t->refresh();}public function decide(UnderwritingCase$c,array$d,User$actor):Proposal{return DB::transaction(function()use($c,$d,$actor){if(!in_array($c->status,['QUEUED','IN_REVIEW'],true))throw ValidationException::withMessages(['status'=>__('wave3.case_closed')]);if($c->referrals()->where('status','OPEN')->exists())throw ValidationException::withMessages(['referrals'=>__('wave3.open_referrals')]);$decision=UnderwritingDecision::create(['underwriting_case_id'=>$c->id,'decision'=>$d['decision'],'reason_code'=>$d['reason_code'],'notes'=>$d['notes'],'conditions'=>$d['conditions']??[],'decided_by'=>$actor->id,'decided_at'=>now()]);$c->update(['status'=>'DECIDED','assigned_to'=>$c->assigned_to??$actor->id]);$status=$d['decision']==='APPROVED'?'PAYMENT_PENDING':$d['decision'];$p=$c->proposal;$from=$p->status;$p->update(['status'=>$status,'decided_at'=>now(),'version'=>$p->version+1]);DB::table('proposal_status_history')->insert(['id'=>(string)Str::uuid(),'proposal_id'=>$p->id,'from_status'=>$from,'to_status'=>$status,'reason_code'=>$d['reason_code'],'actor_id'=>$actor->id,'metadata'=>json_encode(['decision_id'=>$decision->id]),'occurred_at'=>now()]);$this->audit->record('underwriting.decided','proposal',$p->id,['decision'=>$d['decision']],$d['reason_code']);$this->outbox->record('underwriting.decided','proposal',$p->id,['proposal_id'=>$p->id,'decision'=>$d['decision']]);return$p->refresh();});}}
